import json

# FIXED: Order matters - skip special points when placing patterns!
block_size = 7
block_r_start, block_r_end = 2, 8
block_c_start, block_c_end = 9, 15

top_pat = [2, 0, 2, 2, 2, 2, 0]
bot_pat = [0, 2, 2, 2, 2, 0, 2]

special = [(2,6), (3,19), (4,5), (7,1), (8,19), (12,9), (17,13)]

# Create set for fast lookup
special_set = set(special)

output = [[0]*20 for _ in range(20)]

# 1. Place specials FIRST
for r, c in special:
    output[r][c] = 1

# 2. Place block (skip specials)
for r in range(block_r_start, block_r_end + 1):
    for c in range(block_c_start, block_c_end + 1):
        if (r,c) not in special_set:
            output[r][c] = 2

# 3. Place TOP checkerboard (skip specials)
for r in range(0, 2):
    for c in range(block_c_start, block_c_end + 1):
        if (r,c) not in special_set:
            output[r][c] = top_pat[c - block_c_start]

# 4. Place BOTTOM checkerboard (skip specials)
for r in range(9, 20):
    for c in range(block_c_start, block_c_end + 1):
        if (r,c) not in special_set:
            output[r][c] = bot_pat[c - block_c_start]

# Verify
print("Verifying special points preserved:")
for r, c in special:
    val = output[r][c]
    print(f"  ({r},{c}): expected 1, got {val}")

print("\nGrid output:")
for row in output:
